SN=E('Social Studies','ኅብረተሰብ ትምህርት');B='(d=>K8.drills(d))'
def U(n,title,drills,extra,exam,nt,summ,foot):
    unit(f'g8-social-{n}','social',SN,E(f'Chapter {n}',f'ምዕራፍ {n}'),E(*title),E(f'Built on the Grade 8 Social Studies student book (ANRS), Chapter {n}: {foot[0]}.',f'በ8ኛ ክፍል የኅብረተሰብ ትምህርት መጽሐፍ ምዕራፍ {n} ላይ የተመሰረተ፦ {foot[1]}።'),B,drills,extra,exam,nt,summ)

