U(1,('Continents, landforms, atmosphere and map reading','አህጉራት፣ ምድረ ቅርጾች፣ ከባቢ አየርና የካርታ ንባብ'),[
 D('mapscale',('Distance from a map','ርቀትን ከካርታ'),('A map scale such as 1 : 50,000 means 1 cm on the map is 50,000 cm (0.5 km) on the ground.','እንደ 1 : 50,000 ያለ መስፈርት በካርታው 1 ሴ.ሜ በመሬት ላይ 50,000 ሴ.ሜ (0.5 ኪ.ሜ) ማለት ነው።'),5),
 D('mapconv',('Change the scale into words','መስፈርቱን ወደ ቃላት ለውጡ'),('Scales can be written as a ratio (1 : 100,000), in words (1 cm to 1 km) or as a line (graphic) scale.','መስፈርት በምጣኔ (1 : 100,000)፣ በቃላት (1 ሴ.ሜ ለ1 ኪ.ሜ) ወይም በመስመር ሊጻፍ ይችላል።'),4),
 D('temp',('Altitude and temperature','ከፍታና ሙቀት'),('Latitude, altitude, distance from the sea, winds and mountain barriers control weather and climate.','ኬክሮስ፣ ከፍታ፣ ከባሕር ያለ ርቀት፣ ነፋስና የተራራ እግድ የአየር ጠባይንና የአየር ንብረትን ይቆጣጠራሉ።'),4)],
 [sortm(('Internal or external force?','ውስጠ-መጥ ወይስ ውጨ-መጥ ኃይል?'),('Internal forces come from inside the Earth (folding, faulting, volcanoes). External forces work on the surface (weathering, erosion and deposition by rivers, wind, ice, waves).','ውስጠ-መጥ ኃይሎች ከመሬት ውስጥ ይመነጫሉ (ቅልብሽ፣ ዝንፈት፣ እሳተ ገሞራ)። ውጨ-መጥ ኃይሎች በገጸ ምድር ይሠራሉ (በወንዝ፣ በነፋስ፣ በበረዶ፣ በሞገድ መፈርፈር፣ መሸርሸርና ማከማቸት)።'),[('Internal','ውስጠ-መጥ'),('External','ውጨ-መጥ')],
  [(('a volcano forming a mountain','ተራራ የሚሠራ እሳተ ገሞራ'),0),(('rocks folding into ridges','ዓለቶች ተቀልብሰው ሸንተረር ሲሠሩ'),0),(('a fault making the Rift Valley','የስምጥ ሸለቆን የሠራ ዝንፈት'),0),(('a river cutting a gorge','ወንዝ ገደል ሲቆርጥ'),1),(('wind shaping sand dunes','ነፋስ የአሸዋ ክምር ሲቀርጽ'),1),(('waves wearing a cliff','ሞገድ ገደልን ሲሸረሽር'),1)]),
  quiz(('Continents, water and air','አህጉራት፣ ውኃና አየር'),('There are 7 continents and 5 oceans. Air is about 78% nitrogen, 21% oxygen, 0.9% argon and 0.03% carbon dioxide. Weather is short-term; climate is the long-term average.','7 አህጉራትና 5 ውቅያኖሶች አሉ። አየር በግምት 78% ናይትሮጅን፣ 21% ኦክስጅን፣ 0.9% አርገንና 0.03% ካርቦን ዳይኦክሳይድ ነው። የአየር ጠባይ የአጭር ጊዜ፣ የአየር ንብረት የረጅም ጊዜ አማካይ ነው።'),[
  q('The largest continent is…','ትልቁ አህጉር…',[('Asia','እስያ'),('Africa','አፍሪካ'),('Europe','አውሮፓ')]),
  q('The gas that makes up most of the air is…','አብዛኛውን አየር የሚይዘው ጋዝ…',[('nitrogen','ናይትሮጅን'),('oxygen','ኦክስጅን'),('carbon dioxide','ካርቦን ዳይኦክሳይድ')]),
  q('"It rained heavily this morning in Bahir Dar" describes…','"ዛሬ ጠዋት ባሕር ዳር ኃይለኛ ዝናብ ዘነበ" የሚገልጸው…',[('weather','የአየር ጠባይ'),('climate','የአየር ንብረት')]),
  q('The layer of the atmosphere we live in is the…','የምንኖርበት የከባቢ አየር ንብርብር…',[('troposphere','ትሮፖስፌር'),('stratosphere','ስትራቶስፌር'),('thermosphere','ቴርሞስፌር')]),
  q('GPS finds positions using…','ጂፒኤስ ቦታን የሚያገኘው በ…',[('satellites','ሳተላይቶች'),('rivers','ወንዞች'),('the compass only','በኮምፓስ ብቻ')])])],
 [q('How many continents are there?','ስንት አህጉራት አሉ?',['7','5','6']),q('Folding and faulting are…','ቅልብሽና ዝንፈት…',[('internal forces','ውስጠ-መጥ ኃይሎች'),('external forces','ውጨ-መጥ ኃይሎች')]),q('Map scale 1 : 100,000: 4 cm on the map = ?','መስፈርት 1 : 100,000፦ በካርታ 4 ሴ.ሜ = ?',['4 km','40 km','0.4 km']),q('Higher places are usually…','ከፍ ያሉ ቦታዎች ብዙ ጊዜ…',[('cooler','ቀዝቃዛ'),('hotter','ሞቃት')]),q('Climate is…','የአየር ንብረት…',[('the long-term average weather of a large area','የሰፊ ቦታ የረጅም ጊዜ አማካይ የአየር ሁኔታ'),('today’s weather','የዛሬው የአየር ጠባይ')])],
 notes(('Internal and external forces shape the continents, the atmosphere controls weather and climate, and maps with scales let us measure the Earth.','ውስጠ-መጥና ውጨ-መጥ ኃይሎች አህጉራትን ይቀርጻሉ፤ ከባቢ አየር የአየር ጠባይንና ንብረትን ይወስናል፤ ካርታና መስፈርት መሬትን እንድንለካ ያስችላሉ።'),
  [('7 continents; oceans, seas, lakes, rivers.','7 አህጉራት፤ ውቅያኖሶች፣ ባሕሮች፣ ሐይቆች፣ ወንዞች።'),('Internal: folding, faulting, volcanoes; external: erosion.','ውስጠ-መጥ፦ ቅልብሽ፣ ዝንፈት፣ እሳተ ገሞራ፤ ውጨ-መጥ፦ መሸርሸር።'),('Air 78% N₂, 21% O₂; weather vs climate and their controls.','አየር 78% N₂፣ 21% O₂፤ የአየር ጠባይና ንብረት ተቆጣጣሪዎቻቸው።'),('Scale: ratio, words, line; distance, area, GPS.','መስፈርት፦ ምጣኔ፣ ቃላት፣ መስመር፤ ርቀት፣ ስፋት፣ ጂፒኤስ።')],
  [('አህጉር','continent','ሰፊ የየብስ ክፍል'),('ከባቢ አየር','atmosphere','ምድርን የሚከብ የአየር ንብርብር'),('የካርታ መስፈርት','map scale','የካርታና የመሬት ርቀት ምጣኔ')],('Weather today, climate for years.','የአየር ጠባይ ለዛሬ፣ የአየር ንብረት ለዓመታት።'),
  [(('Scale 1 : 50,000; road 7 cm on the map. Real length?','መስፈርት 1 : 50,000፤ መንገድ በካርታ 7 ሴ.ሜ። እውነተኛ ርዝመቱ?'),('3.5 km','3.5 ኪ.ሜ')),(('Name 3 controls of climate','3 የአየር ንብረት ተቆጣጣሪዎችን ጥቀሱ'),('latitude, altitude, distance from the sea','ኬክሮስ፣ ከፍታ፣ ከባሕር ያለ ርቀት'))],
  (('Village weather station','የመንደር የአየር ሁኔታ ጣቢያ'),('Farmers plan with weather data. Run a simple station for two weeks.','ገበሬዎች በአየር ሁኔታ መረጃ ያቅዳሉ። ለሁለት ሳምንት ቀላል ጣቢያ አካሂዱ።'),[('Make a rain gauge from a bottle and a ruler.','ከጠርሙስና ከማስመሪያ የዝናብ መለኪያ ሥሩ።'),('Record rain, temperature and wind direction daily.','ዝናብን፣ ሙቀትንና የነፋስ አቅጣጫን በየቀኑ መዝግቡ።'),('Draw graphs and describe the weather pattern.','ግራፎችን ሳሉና የአየር ሁኔታውን ይዘት ግለጹ።'),('Share a short forecast with your class.','አጭር ትንበያ ለክፍላችሁ አጋሩ።')])),
 sm(('Earth’s surface, air and maps','የመሬት ገጽ፣ አየርና ካርታ'),[('Continents and water','አህጉራትና ውኃ'),('Landform forces','ምድረ ቅርጽ ሠሪ ኃይሎች'),('Atmosphere, weather, climate','ከባቢ አየር፣ ጠባይ፣ ንብረት'),('Scale, distance, GPS','መስፈርት፣ ርቀት፣ ጂፒኤስ')]),
 ('continents and water bodies, landform-shaping forces, the atmosphere, weather and climate, map scale, distance, area and GPS','አህጉራትና ውሃማ አካላት፣ የመሬት ገጽ ቀራጺ ኃይሎች፣ ከባቢ አየር፣ የአየር ጠባይና ንብረት፣ የካርታ መስፈርት፣ ርቀት፣ ስፋትና ጂፒኤስ'))

