U(2,('Culture and economic activities','ባህልና ምጣኔ ሀብታዊ እንቅስቃሴዎች'),[],
 [sortm(('Primary, secondary or tertiary?','የመጀመሪያ፣ ሁለተኛ ወይስ ሦስተኛ ደረጃ?'),('Primary activities take resources directly from nature. Secondary activities process them into products. Tertiary activities provide services.','የመጀመሪያ ደረጃ እንቅስቃሴዎች ሀብትን በቀጥታ ከተፈጥሮ ይወስዳሉ። ሁለተኛ ደረጃዎቹ ወደ ምርት ይቀይሯቸዋል። ሦስተኛ ደረጃዎቹ አገልግሎት ይሰጣሉ።'),[('Primary','የመጀመሪያ'),('Secondary','ሁለተኛ'),('Tertiary','ሦስተኛ')],
  [(('farming teff','ጤፍ ማረስ'),0),(('fishing in Lake Tana','በጣና ሐይቅ ዓሣ ማጥመድ'),0),(('mining gold','ወርቅ ማውጣት'),0),(('milling flour','ዱቄት መፍጨት'),1),(('making shoes from leather','ከቆዳ ጫማ መሥራት'),1),(('building a house','ቤት መገንባት'),1),(('teaching','ማስተማር'),2),(('banking','የባንክ አገልግሎት'),2),(('transport by bus','በአውቶቡስ ማጓጓዝ'),2)]),
  quiz(('Culture, trade and tax','ባህል፣ ንግድና ግብር'),('Culture is a people’s way of life: language, religion, symbols and values. Trade can be local, national or international. Supply and demand set prices, consumers have rights, and taxes pay for public services.','ባህል የአንድ ሕዝብ የአኗኗር ዘይቤ ነው፦ ቋንቋ፣ ሃይማኖት፣ ምልክትና እሴቶች። ንግድ አካባቢያዊ፣ ሀገራዊ ወይም ዓለም አቀፋዊ ሊሆን ይችላል። አቅርቦትና ፍላጎት ዋጋን ይወስናሉ፤ ሸማቾች መብት አላቸው፤ ግብር ለሕዝባዊ አገልግሎት ይከፍላል።'),[
  q('Which is an element of culture?','የባህል ይዘት የሆነው?',[('language','ቋንቋ'),('rainfall','ዝናብ'),('altitude','ከፍታ')]),
  q('When demand rises and supply stays the same, prices usually…','ፍላጎት ሲጨምርና አቅርቦት ሳይለወጥ ሲቀር ዋጋ ብዙ ጊዜ…',[('rise','ይጨምራል'),('fall','ይቀንሳል')]),
  q('Exporting coffee to other countries is…','ቡናን ወደ ሌሎች ሀገራት መላክ…',[('international trade','ዓለም አቀፍ ንግድ'),('local trade','አካባቢያዊ ንግድ')]),
  q('Selling expired food breaks…','ጊዜው ያለፈ ምግብ መሸጥ የሚጥሰው…',[('consumer rights','የሸማቾች መብት'),('traffic rules','የትራፊክ ሕግ')]),
  q('Taxes are used to…','ግብር የሚውለው…',[('build roads, schools and clinics','መንገድ፣ ትምህርት ቤትና ጤና ጣቢያ ለመገንባት'),('pay only for festivals','ለበዓላት ብቻ ለመክፈል')])])],
 [q('Weaving cloth from cotton is a … activity.','ከጥጥ ልብስ መሸመን … ደረጃ እንቅስቃሴ ነው።',[('secondary','ሁለተኛ'),('primary','የመጀመሪያ'),('tertiary','ሦስተኛ')]),q('Health care is a … activity.','የጤና አገልግሎት … ደረጃ እንቅስቃሴ ነው።',[('tertiary','ሦስተኛ'),('primary','የመጀመሪያ')]),q('In Ethiopia’s federal system, taxes are collected by…','በኢትዮጵያ ፌዴራላዊ ሥርዓት ግብር የሚሰበስቡት…',[('the federal government and the regions','የፌዴራል መንግሥትና ክልሎች'),('only the regions','ክልሎች ብቻ')]),q('Globalisation can…','ዓለም አቀፋዊነት…',[('change social and cultural values','ማኅበራዊና ባህላዊ እሴቶችን ሊለውጥ ይችላል'),('stop all trade','ንግድን ሁሉ ሊያቆም')])],
 notes(('Culture shapes how people live; economies grow through primary, secondary and tertiary activities, fair trade and taxes.','ባህል ሰዎች እንዴት እንደሚኖሩ ይቀርጻል፤ ኢኮኖሚ በመጀመሪያ፣ በሁለተኛና በሦስተኛ ደረጃ እንቅስቃሴዎች፣ በፍትሐዊ ንግድና በግብር ያድጋል።'),
  [('Culture: language, religion, symbols, values; diversity.','ባህል፦ ቋንቋ፣ ሃይማኖት፣ ምልክት፣ እሴት፤ ብዝኃነት።'),('Primary → secondary → tertiary.','የመጀመሪያ → ሁለተኛ → ሦስተኛ።'),('Trade: supply, demand, consumer rights.','ንግድ፦ አቅርቦት፣ ፍላጎት፣ የሸማች መብት።'),('Government revenue and tax build the country.','የመንግሥት ገቢና ግብር ሀገርን ይገነባሉ።')],
  [('ባህል','culture','የአኗኗር ዘይቤ'),('አቅርቦት','supply','ለገበያ የቀረበ ምርት'),('ግብር','tax','ለሀገር ልማት የሚከፈል')],('Take it, make it, serve it.','ውሰድ፣ ሥራ፣ አገልግል።'),
  [(('Give one example of each level of activity','የእያንዳንዱን ደረጃ አንድ ምሳሌ ስጡ'),('farming, milling, transport','ማረስ፣ መፍጨት፣ ማጓጓዝ')),(('Why should citizens pay tax?','ዜጎች ለምን ግብር መክፈል አለባቸው?'),('to fund public services and development','ሕዝባዊ አገልግሎትንና ልማትን ለመደገፍ'))],
  (('Local value-chain map','የአካባቢ የእሴት ሰንሰለት ካርታ'),('Follow one local product from field to customer and find a business idea in it.','አንድን የአካባቢ ምርት ከማሳ እስከ ደንበኛ ተከተሉና የንግድ ሐሳብ ፈልጉበት።'),[('Choose a product: honey, teff, coffee or milk.','ምርት ምረጡ፦ ማር፣ ጤፍ፣ ቡና ወይም ወተት።'),('Interview a producer, a processor and a seller.','አምራች፣ አቀናባሪና ሻጭ ቃለ መጠይቅ አድርጉ።'),('Draw the chain and the price at each step.','ሰንሰለቱንና በእያንዳንዱ እርምጃ ያለውን ዋጋ ሳሉ።'),('Suggest one step you could add value to.','እሴት ልትጨምሩበት የምትችሉትን አንድ እርምጃ አቅርቡ።')])),
 sm(('How people live and earn','ሰዎች እንዴት ይኖራሉ፣ ያገኛሉ'),[('Culture and diversity','ባህልና ብዝኃነት'),('Three levels of activity','ሦስት የእንቅስቃሴ ደረጃዎች'),('Trade and markets','ንግድና ገበያ'),('Revenue and tax','ገቢና ግብር')]),
 ('culture and diversity, primary, secondary and tertiary economic activities, trade and markets, government revenue and tax','ባህልና ብዝኃነት፣ የመጀመሪያ፣ ሁለተኛና ሦስተኛ ደረጃ ምጣኔ ሀብታዊ እንቅስቃሴዎች፣ ንግድና ገበያ፣ የመንግሥት ገቢና ግብር'))

