U(3,('Natural resources and development','የተፈጥሮ ሀብቶችና ልማት'),[],
 [sortm(('Renewable or non-renewable?','የሚታደስ ወይስ የማይታደስ?'),('Renewable resources can be replaced or will not run out if used wisely. Non-renewable resources took millions of years to form and can run out.','የሚታደሱ ሀብቶች በአግባቡ ከተጠቀምንባቸው ይተካሉ ወይም አያልቁም። የማይታደሱ ሀብቶች ለመፈጠር ሚሊዮኖች ዓመታት የፈጁ ሲሆን ሊያልቁ ይችላሉ።'),[('Renewable','የሚታደስ'),('Non-renewable','የማይታደስ')],
  [(('sunlight','የፀሐይ ብርሃን'),0),(('wind','ነፋስ'),0),(('forests (if replanted)','ደን (መልሶ ከተተከለ)'),0),(('river water','የወንዝ ውኃ'),0),(('petroleum','ነዳጅ ዘይት'),1),(('coal','የድንጋይ ከሰል'),1),(('gold','ወርቅ'),1),(('natural gas','የተፈጥሮ ጋዝ'),1)]),
  quiz(('Misuse and conflict','ያልተገባ አጠቃቀምና ግጭት'),('Careless use causes deforestation, soil erosion, pollution and loss of wildlife. Resources are unevenly spread, so scarcity can lead to conflict over land, water or grazing. Conflicts come from economic interests, values or power, and are resolved by negotiation, mediation and arbitration.','ግድ የለሽ አጠቃቀም የደን መመናመንን፣ የአፈር መሸርሸርን፣ ብክለትንና የዱር እንስሳት መጥፋትን ያስከትላል። ሀብቶች እኩል ስለማይሰራጩ እጥረት በመሬት፣ በውኃ ወይም በግጦሽ ላይ ግጭት ሊያስከትል ይችላል። ግጭቶች ከኢኮኖሚ፣ ከእሴትና ከሥልጣን ይነሳሉ፤ በድርድር፣ በሽምግልናና በዳኝነት ይፈታሉ።'),[
  q('Cutting forests faster than they grow causes…','ደን ከሚያድገው በላይ በፍጥነት መቁረጥ የሚያስከትለው…',[('deforestation and erosion','የደን መመናመንና መሸርሸር'),('more rain','ብዙ ዝናብ')]),
  q('Two villages argue over a spring. A respected elder helps them agree. This is…','ሁለት መንደሮች በምንጭ ይጣላሉ። የተከበሩ ሽማግሌ እንዲስማሙ ይረዷቸዋል። ይህ…',[('mediation','ሽምግልና'),('arbitration in court','በፍርድ ቤት ዳኝነት'),('war','ጦርነት')]),
  q('The three main sources of conflict are…','ሦስቱ ዋና ዋና የግጭት ምንጮች…',[('economic, values and power','ኢኮኖሚ፣ እሴትና ሥልጣን'),('rain, sun and wind','ዝናብ፣ ፀሐይና ነፋስ')]),
  q('Sustainable use means…','ዘላቂ አጠቃቀም ማለት…',[('meeting our needs while leaving enough for the future','ለወደፊት በቂ እየተውን ፍላጎታችንን ማሟላት'),('using everything now','ሁሉንም አሁን መጠቀም')])])],
 [q('Which is non-renewable?','የማይታደሰው?',[('coal','የድንጋይ ከሰል'),('solar energy','የፀሐይ ኃይል'),('wind','ነፋስ')]),q('Terracing protects…','እርከን የሚጠብቀው…',[('soil','አፈርን'),('gold','ወርቅን'),('oil','ነዳጅን')]),q('A judge deciding a land case is…','የመሬት ክርክርን የሚወስን ዳኛ…',[('arbitration/adjudication','ዳኝነት'),('negotiation','ድርድር')]),q('Natural resources are useful to people when…','የተፈጥሮ ሀብቶች ለሰው ጠቃሚ የሚሆኑት…',[('people use knowledge to turn them into wealth','ሰዎች በዕውቀት ወደ ሀብት ሲቀይሯቸው'),('they are never touched','ፈጽሞ ሳይነኩ')])],
 notes(('Natural resources power development, but they must be used sustainably and shared fairly to avoid damage and conflict.','የተፈጥሮ ሀብቶች ልማትን ያንቀሳቅሳሉ፤ ነገር ግን ጉዳትንና ግጭትን ለማስወገድ በዘላቂነት ሊጠቀሙና በፍትሐዊነት ሊከፋፈሉ ይገባል።'),
  [('Renewable vs non-renewable resources.','የሚታደሱና የማይታደሱ ሀብቶች።'),('Use changes over time with technology.','አጠቃቀም በቴክኖሎጂ ከጊዜ ጋር ይለወጣል።'),('Misuse: deforestation, erosion, pollution.','ያልተገባ አጠቃቀም፦ የደን መመናመን፣ መሸርሸር፣ ብክለት።'),('Scarcity → conflict → negotiation, mediation, arbitration.','እጥረት → ግጭት → ድርድር፣ ሽምግልና፣ ዳኝነት።')],
  [('የተፈጥሮ ሀብት','natural resource','ከተፈጥሮ የምናገኘው ጠቃሚ ነገር'),('ዘላቂ','sustainable','ለወደፊትም የሚበቃ'),('ሽምግልና','mediation','በሦስተኛ ወገን ማስታረቅ')],('Use, renew, share.','ተጠቀሙ፣ አድሱ፣ አጋሩ።'),
  [(('Give two effects of deforestation','የደን መመናመን ሁለት ውጤቶችን ስጡ'),('soil erosion, less rain and wildlife','የአፈር መሸርሸር፣ የዝናብና የዱር እንስሳት መቀነስ')),(('Name three ways to resolve conflict','ግጭትን የሚፈቱ ሦስት መንገዶችን ጥቀሱ'),('negotiation, mediation, arbitration','ድርድር፣ ሽምግልና፣ ዳኝነት'))],
  (('Water-sharing plan for a village','የመንደር የውኃ መጋራት እቅድ'),('Design a fair plan for a spring that two groups use.','ሁለት ቡድኖች ለሚጠቀሙበት ምንጭ ፍትሐዊ እቅድ ንደፉ።'),[('List who uses the water and for what.','ውኃውን ማን ለምን እንደሚጠቀም ዘርዝሩ።'),('Estimate daily litres for each need.','ለእያንዳንዱ ፍላጎት የዕለት ሊትር ገምቱ።'),('Propose a timetable and protection rules.','የጊዜ ሰሌዳና የጥበቃ ደንቦችን አቅርቡ።'),('Hold a class mediation role-play.','የክፍል የሽምግልና ጨዋታ አድርጉ።')])),
 sm(('Use wisely, share fairly','በጥበብ ተጠቀሙ፣ በፍትሐዊነት አጋሩ'),[('Types of resources','የሀብት ዓይነቶች'),('Changing use','የሚለወጥ አጠቃቀም'),('Effects of misuse','የያልተገባ አጠቃቀም ውጤት'),('Conflict resolution','የግጭት አፈታት')]),
 ('caring for the environment for sustainable development, effects of careless use, access to resources and conflict resolution','ለዘላቂ ልማት አካባቢን መንከባከብ፣ የግድ የለሽ አጠቃቀም ውጤቶች፣ የሀብት ተደራሽነትና የግጭት አፈታት'))

