U(5,('Africa after 1500','አፍሪካ ከ1500 በኋላ'),[],
 [order(('Africa’s path to freedom','የአፍሪካ የነጻነት ጉዞ'),('Slavery and colonialism were followed by resistance, independence and unity.','ባርነትና ቅኝ ግዛት በተቃውሞ፣ በነጻነትና በአንድነት ተከተሉ።'),('Tap from earliest to latest.','ከቀደመው እስከ ኋለኛው ንኩ።'),
  [(('Events','ሁነቶች'),[('Atlantic slave trade grows (1500s–1800s)','የአትላንቲክ የባሪያ ንግድ ይስፋፋል (1500ዎቹ–1800ዎቹ)'),('Berlin Conference divides Africa (1884–85)','የበርሊን ጉባኤ አፍሪካን ይቀራመታል (1884–85)'),('Second World War weakens colonial powers (1939–45)','ሁለተኛው የዓለም ጦርነት ቅኝ ገዥዎችን ያዳክማል (1939–45)'),('Ghana becomes independent (1957)','ጋና ነጻ ትወጣለች (1957)'),('OAU founded in Addis Ababa (1963)','የአፍሪካ አንድነት ድርጅት በአዲስ አበባ ይመሠረታል (1963)')])]),
  quiz(('Slavery, colonialism and resistance','ባርነት፣ ቅኝ ግዛትና ተቃውሞ'),('Millions of Africans were taken to the Americas and the Caribbean, often for sugar plantations. Europeans then colonised Africa for raw materials and markets. Leaders such as Samori Touré resisted; after 1945 most countries won independence.','በሚሊዮን የሚቆጠሩ አፍሪካውያን ወደ አሜሪካና ካሪቢያን ተወሰዱ፤ ብዙ ጊዜ ለሸንኮራ አገዳ እርሻ። ከዚያ አውሮፓውያን ለጥሬ ዕቃና ለገበያ አፍሪካን ቅኝ ገዙ። እንደ ሳሞሪ ቱሬ ያሉ መሪዎች ተቋቋሙ፤ ከ1945 በኋላ አብዛኞቹ ሀገራት ነጻነታቸውን አገኙ።'),[
  q('The main aim of the Berlin Conference was to…','የበርሊን ጉባኤ ዋና ዓላማ…',[('divide Africa without war among Europeans','አፍሪካን በአውሮፓውያን መካከል ያለ ጦርነት መቀራመት'),('free African slaves','የአፍሪካ ባሪያዎችን ነጻ ማውጣት')]),
  q('Demand for slave labour grew with the spread of…','የባሪያ ጉልበት ፍላጎት የጨመረው በ… መስፋፋት',[('sugar-cane plantations','የሸንኮራ አገዳ እርሻዎች'),('railways','የባቡር መንገዶች')]),
  q('A strong anti-colonial leader in West Africa was…','በምዕራብ አፍሪካ ጠንካራ ፀረ-ቅኝ ግዛት መሪ…',[('Samori Touré','ሳሞሪ ቱሬ'),('Napoleon','ናፖሊዮን')]),
  q('The OAU headquarters was in…','የአፍሪካ አንድነት ድርጅት ዋና መቀመጫ…',[('Addis Ababa','አዲስ አበባ'),('Accra','አክራ'),('Cairo','ካይሮ')]),
  q('In 2002 the OAU was replaced by the…','በ2002 የአፍሪካ አንድነት ድርጅትን የተካው…',[('African Union','የአፍሪካ ኅብረት'),('United Nations','የተባበሩት መንግሥታት')])])],
 [q('Europeans colonised Africa mainly for…','አውሮፓውያን አፍሪካን የቀኙት በዋናነት ለ…',[('raw materials and markets','ጥሬ ዕቃና ገበያ'),('tourism','ቱሪዝም')]),q('The OAU was founded in…','የአፍሪካ አንድነት ድርጅት የተመሠረተው በ…',['1963','1896','1945']),q('Which event sped up African independence?','የአፍሪካን ነጻነት ያፋጠነው?',[('the Second World War','ሁለተኛው የዓለም ጦርነት'),('the Renaissance','ዘመነ ሕዳሴ')]),q('Which African country was never colonised (apart from 1936–41 occupation)?','(ከ1936–41 ወረራ በቀር) በቅኝ ያልተገዛችው የአፍሪካ ሀገር?',[('Ethiopia','ኢትዮጵያ'),('Kenya','ኬንያ'),('Ghana','ጋና')])],
 notes(('After 1500 Africa suffered the slave trade and colonialism, resisted, won independence after 1945 and united in the OAU (1963), now the African Union.','ከ1500 በኋላ አፍሪካ የባሪያ ንግድንና ቅኝ ግዛትን ተሰቃየች፣ ተቋቋመች፣ ከ1945 በኋላ ነጻነቷን አገኘች፣ በአፍሪካ አንድነት ድርጅት (1963) ተባበረች፤ አሁን የአፍሪካ ኅብረት ነው።'),
  [('Slave trade to the Americas and the Caribbean.','ወደ አሜሪካና ካሪቢያን የባሪያ ንግድ።'),('Colonial rule after the Berlin Conference.','ከበርሊን ጉባኤ በኋላ የቅኝ አገዛዝ።'),('Resistance and independence (1950s–60s).','ተቃውሞና ነጻነት (1950ዎቹ–60ዎቹ)።'),('OAU 1963 in Addis Ababa → African Union.','የአፍሪካ አንድነት ድርጅት 1963 በአዲስ አበባ → የአፍሪካ ኅብረት።')],
  [('ቅኝ ግዛት','colonialism','የሌላ ሀገርን መሬትና ሕዝብ መግዛት'),('ነጻነት','independence','ራስን መግዛት'),('አንድነት','unity','በጋራ መቆም')],('Taken, ruled, resisted, freed, united.','ተወሰደ፣ ተገዛ፣ ተቋቋመ፣ ነጻ ወጣ፣ ተባበረ።'),
  [(('Give two effects of colonialism on Africans','የቅኝ ግዛት ሁለት ተጽዕኖዎችን ስጡ'),('loss of land and resources; artificial borders','የመሬትና የሀብት መጥፋት፤ ሰው ሠራሽ ድንበሮች')),(('Why was Addis Ababa chosen for the OAU?','የአፍሪካ አንድነት ድርጅት ለምን በአዲስ አበባ ሆነ?'),('Ethiopia’s independence and role in African unity','የኢትዮጵያ ነጻነትና በአፍሪካ አንድነት ያላት ሚና'))],
  (('Pan-African fact cards','የፓን አፍሪካ እውነታ ካርዶች'),('Create a card game that teaches African independence dates.','የአፍሪካን የነጻነት ቀናት የሚያስተምር የካርድ ጨዋታ ሥሩ።'),[('Choose 12 African countries.','12 የአፍሪካ ሀገራትን ምረጡ።'),('Find each independence year and one leader.','የእያንዳንዱን የነጻነት ዓመትና አንድ መሪ ፈልጉ።'),('Make cards with a flag drawing on the front and facts on the back.','ፊት ለፊት ሰንደቅ ዓላማ፣ ጀርባ ላይ እውነታ ያለው ካርድ ሥሩ።'),('Play "order the dates" with classmates.','ከክፍል ጓደኞች ጋር "ቀኖቹን ደርድሩ" ተጫወቱ።')])),
 sm(('From chains to unity','ከሰንሰለት ወደ አንድነት'),[('Slave trade','የባሪያ ንግድ'),('Colonial rule','የቅኝ አገዛዝ'),('Resistance and independence','ተቃውሞና ነጻነት'),('OAU and AU','አአድ እና አኅ')]),
 ('slavery and the slave trade, European colonialism, African resistance, independence and the OAU','ባርነትና የባሪያ ንግድ፣ የአውሮፓ ቅኝ ግዛት፣ የአፍሪካውያን ተቃውሞ፣ ነጻነትና የአፍሪካ አንድነት ድርጅት'))

