 [q('Greenhouse gases trap…','ሙቀት አማቂ ጋዞች የሚይዙት…',[('heat','ሙቀት'),('water','ውኃ')]),q('Which is NOT a soil conservation method?','የአፈር ጥበቃ ዘዴ ያልሆነው?',[('ploughing up and down slopes','በተዳፋት ቁልቁል ማረስ'),('terracing','እርከን'),('contour ploughing','ከፍታን ተከትሎ ማረስ')]),q('Protecting forests helps to…','ደንን መጠበቅ የሚረዳው…',[('absorb CO₂ and protect water','CO₂ ለመምጠጥና ውኃን ለመጠበቅ'),('increase floods','ጎርፍን ለመጨመር')]),q('Fresh-water demand each year is…','በየዓመቱ የንጹሕ ውኃ ፍላጎት…',[('increasing','እየጨመረ ነው'),('falling','እየቀነሰ ነው')])],
 notes(('Climate change, water shortage and deforestation are linked global problems; we can act through trees, clean energy, water harvesting and care.','የአየር ንብረት ለውጥ፣ የውኃ እጥረትና የደን መመናመን የተሳሰሩ ዓለም አቀፍ ችግሮች ናቸው፤ በዛፍ፣ በንጹሕ ኃይል፣ በውኃ ማሰባሰብና በእንክብካቤ መሥራት እንችላለን።'),
  [('Greenhouse gases → global warming.','ሙቀት አማቂ ጋዞች → የዓለም ሙቀት መጨመር።'),('Effects: less food, health problems, water shortage.','ውጤቶች፦ የምግብ እጥረት፣ የጤና ችግር፣ የውኃ እጥረት።'),('Deforestation: farms, grazing, towns, cutting.','የደን መመናመን፦ እርሻ፣ ግጦሽ፣ ከተማ፣ መቁረጥ።'),('Actions: plant, protect, burn less, innovate.','ተግባራት፦ ትከሉ፣ ጠብቁ፣ ቀንሱ፣ ፍጠሩ።')],
  [('የአየር ንብረት ለውጥ','climate change','የረጅም ጊዜ የአየር ሁኔታ ለውጥ'),('ሙቀት አማቂ ጋዝ','greenhouse gas','ሙቀትን የሚይዝ ጋዝ'),('ደን መመናመን','deforestation','የደን መጥፋት')],('Think global, plant local.','በዓለም ደረጃ አስቡ፣ በአካባቢ ትከሉ።'),
  [(('Give two effects of climate change in Ethiopia','በኢትዮጵያ የአየር ንብረት ለውጥ ሁለት ውጤቶችን ስጡ'),('drought, lower crop yields','ድርቅ፣ የምርት መቀነስ')),(('Give two ways to save water at school','በትምህርት ቤት ውኃ የሚቆጠብባቸውን ሁለት መንገዶች ስጡ'),('fix leaks; harvest rain-water','ፍሳሽን መጠገን፤ የዝናብ ውኃ ማሰባሰብ'))],
  (('Seedling nursery business','የችግኝ ጣቢያ ሥራ'),('Grow seedlings for the community and the Green Legacy campaign.','ለማኅበረሰቡና ለአረንጓዴ አሻራ ዘመቻ ችግኝ አፍሉ።'),[('Collect seeds of local trees (wanza, grevillea, fruit trees).','የአካባቢ ዛፎችን ዘር ሰብስቡ (ዋንዛ፣ ግራቪሊያ፣ የፍራፍሬ ዛፎች)።'),('Plant them in recycled bags with compost.','ከኮምፖስት ጋር በእንደገና በሚጠቀሙ ከረጢቶች ትከሉ።'),('Water and record growth weekly.','በየሳምንቱ አጠጡና እድገቱን መዝግቡ።'),('Sell or donate seedlings and track survival.','ችግኞቹን ሽጡ ወይም ለግሱ፤ መጽደቃቸውንም ተከታተሉ።')])),
